mapper.select:
SELECT p.id AS projectId, p.title AS title, pt.name AS typeName, p.cover_file_id AS coverFileId, p.thumbnail_file_id AS thumbnailFileId, COUNT(ti.id) AS pendingCount, COUNT(DISTINCT ti.item_id) AS itemCount, MIN(ti.created_at) AS oldestCreatedAt, MAX(ti.created_at) AS latestCreatedAt FROM task_instance ti JOIN item_task_node n ON n.id = ti.item_task_node_id AND n.deleted_at IS NULL JOIN item i ON i.id = ti.item_id AND i.deleted_at IS NULL JOIN project p ON p.id = ti.project_id AND p.deleted_at IS NULL AND p.resource_status = 1 AND p.status = 1 LEFT JOIN project_type pt ON pt.id = p.type_id AND pt.deleted_at IS NULL
WHERE ti.deleted_at IS NULL AND ti.status = 1 AND ti.assignee_id IS NULL AND p.org_id = #{params.orgId}
AND p.type_id = #{params.typeId}
AND (p.title LIKE #{params.matchPattern} ESCAPE '!' OR i.title LIKE #{params.matchPattern} ESCAPE '!' OR n.name LIKE #{params.matchPattern} ESCAPE '!')
GROUP BY p.id, p.title, pt.name, p.cover_file_id, p.thumbnail_file_id
ORDER BY latestCreatedAt DESC, p.id DESC
ORDER BY pendingCount DESC, oldestCreatedAt ASC, p.id DESC
ORDER BY oldestCreatedAt ASC, p.id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(DISTINCT p.id) FROM task_instance ti JOIN item_task_node n ON n.id = ti.item_task_node_id AND n.deleted_at IS NULL JOIN item i ON i.id = ti.item_id AND i.deleted_at IS NULL JOIN project p ON p.id = ti.project_id AND p.deleted_at IS NULL AND p.resource_status = 1 AND p.status = 1
WHERE ti.deleted_at IS NULL AND ti.status = 1 AND ti.assignee_id IS NULL AND p.org_id = #{params.orgId}
AND p.type_id = #{params.typeId}
AND (p.title LIKE #{params.matchPattern} ESCAPE '!' OR i.title LIKE #{params.matchPattern} ESCAPE '!' OR n.name LIKE #{params.matchPattern} ESCAPE '!')

SELECT ti.id AS instanceId, ti.project_id AS projectId, ti.item_id AS itemId, ti.status AS status, ti.created_at AS createdAt, n.name AS nodeName, n.sort AS sort, n.parallel_sort AS parallelSort, (n.sort = cur.current_sort) AS isCurrentStage, i.title AS itemTitle FROM task_instance ti JOIN item_task_node n ON n.id = ti.item_task_node_id AND n.deleted_at IS NULL JOIN item i ON i.id = ti.item_id AND i.deleted_at IS NULL JOIN project p ON p.id = ti.project_id AND p.deleted_at IS NULL AND p.resource_status = 1 AND p.status = 1
WHERE ti.deleted_at IS NULL AND ti.project_id IN #{id}
AND (p.title LIKE #{params.matchPattern} ESCAPE '!' OR i.title LIKE #{params.matchPattern} ESCAPE '!' OR n.name LIKE #{params.matchPattern} ESCAPE '!')
AND p.type_id = #{params.typeId}
ORDER BY ti.project_id, ti.item_id, n.sort, n.parallel_sort, ti.created_at, ti.id

SELECT ti.id AS instanceId, ti.item_id AS itemId, ti.project_id AS projectId, i.title AS itemTitle, p.title AS projectName, n.name AS nodeName, n.sort AS stageSort, ti.claimed_at AS claimedAt FROM task_instance ti JOIN item_task_node n ON n.id = ti.item_task_node_id AND n.deleted_at IS NULL JOIN item i ON i.id = ti.item_id AND i.deleted_at IS NULL JOIN project p ON p.id = ti.project_id AND p.deleted_at IS NULL AND p.resource_status = 1 WHERE ti.deleted_at IS NULL AND ti.status = 2 AND ti.assignee_id = #{userId} AND p.org_id = #{orgId}
ORDER BY ti.claimed_at IS NULL, ti.claimed_at DESC, ti.id DESC
ORDER BY ti.claimed_at IS NULL, ti.claimed_at ASC, ti.id ASC
